// Shows/hides a small inline spinner next to a toggle while its AJAX save is in flight.
function mo2f_toggle_loading(elementId,isLoading){
	if(!elementId){return;}
	var selector=elementId.charAt(0)==="#"?elementId:"#"+elementId;
	var el=document.querySelector(selector);
	if(!el){return;}
	el.disabled=isLoading;
	if(el.tagName!=="INPUT"||el.type!=="checkbox"){return;}
	var container=el.closest(".mo2f_checkbox_container")||el.parentElement;
	if(!container){return;}
	var spinner=container.querySelector(".mo2f-toggle-spinner");
	if(isLoading){
		if(!spinner){
			spinner=document.createElement("span");
			spinner.className="mo2f-toggle-spinner";
			container.appendChild(spinner);
		}
	}else if(spinner){
		spinner.remove();
	}
}
